import { initialMockData } from '../data/mockData'
import type { LocalPosService } from '../services/localPosService'

/**
 * Seeds the demo catalog from `src/data/mockData.ts` through the public service
 * API. Test and development helper ONLY: mock data must never reach the APK, so
 * the production service no longer knows this file exists (docs/HANDOFF.md § 1).
 *
 * Call it only on an empty catalog. Ids are generated by the service, not copied
 * from the mock data.
 */
export async function seedDemoCatalog(service: LocalPosService) {
  const existing = await service.getBootstrap()
  if (existing.products.length) throw new Error('seedDemoCatalog: katalog harus kosong.')

  const categoryIds = new Map<string, string>()
  for (const category of initialMockData.categories) {
    // `all` is the pseudo-category the bootstrap adds for the UI filter row.
    if (category.id === 'all') continue
    const saved = await service.saveCategory({ name: category.name, color: category.color })
    categoryIds.set(category.id, saved.id)
  }

  for (const product of initialMockData.products) {
    const categoryId = categoryIds.get(product.categoryId)
    if (!categoryId) throw new Error(`seedDemoCatalog: kategori ${product.categoryId} tidak ada di mock data.`)
    await service.saveProduct({
      name: product.name,
      categoryId,
      description: product.description,
      accent: product.accent,
      featured: Boolean(product.featured),
      variants: product.variants.map((variant) => ({ name: variant.name, price: variant.price, sku: variant.sku, stock: variant.stock })),
    })
  }

  return service.getBootstrap()
}
